// --- MOTOR DE MAPAS CORREGIDO ---
export const MapNode = (m = mod(), options = {}) => {
  const container = Alset.createNode("div", m, null);
  const { center = [40.7128, -74.0060], zoom = 12, marker = "Alset HQ" } = options;
  const id = `map-${Math.random().toString(36).substr(2, 9)}`;
  container.id = id;

  const loadLeaflet = () => {
    if (window.L) {
      const map = L.map(id).setView(center, zoom);
      L.tileLayer('https://{s}.basemaps.cartocdn.com/dark_all/{z}/{x}/{y}{r}.png').addTo(map);
      L.marker(center).addTo(map).bindPopup(marker).openPopup();
      return;
    }
    const link = document.createElement('link');
    link.rel = 'stylesheet'; link.href = 'https://unpkg.com/leaflet@1.9.4/dist/leaflet.css';
    document.head.appendChild(link);
    const script = document.createElement('script');
    script.src = 'https://unpkg.com/leaflet@1.9.4/dist/leaflet.js';
    script.onload = () => loadLeaflet();
    document.head.appendChild(script);
  };
  setTimeout(loadLeaflet, 100);
  return container;
};

// --- GESTOR DE HISTORIAL ---
const history = [];
const historyManager = {
  push: (code) => {
    if (history.length === 0 || history[history.length - 1] !== code) {
      history.push(code);
      if (history.length > 100) history.shift();
    }
  },
  undo: (state) => {
    if (history.length > 1) {
      history.pop();
      state.set(history[history.length - 1]);
    }
  }
};

